def split_camel_case(name: str) -> list[str]:
    words: list[str] = []
    current = ""
    for ch in name:
        if ch.isupper() and current:
            words.append(current)
            current = ch
        else:
            current += ch
    if current:
        words.append(current)
    return words

def parse_version_string(version: str) -> tuple[int, ...]:
    s = version.strip()
    if s[:1] in ("v", "V"):
        s = s[1:]
    if not s:
        return ()
    parts = []
    for part in s.split("."):
        if not (part.isascii() and part.isdigit()):
            raise ValueError(f"invalid version component: {part!r}")
        parts.append(int(part))
    return tuple(parts)

def count_sentences(text: str) -> int:
    count = 0
    pending = False
    for ch in text:
        if ch in ".!?":
            if pending:
                count += 1
                pending = False
        elif not ch.isspace():
            pending = True
    return count + (1 if pending else 0)

def parse_dimension(spec: str) -> tuple[int, int]:
    parts = spec.lower().split("x")
    if len(parts) == 2:
        w, h = (p.strip() for p in parts)
        if all(p.isascii() and p.isdigit() and int(p) > 0 for p in (w, h)):
            return int(w), int(h)
    raise ValueError(f"invalid dimension: {spec!r}")

