def squeeze_blank_lines(text: str, max_blank: int = 1) -> str:
    out: list[str] = []
    run = 0
    for line in text.split("\n"):
        if line.strip():
            run = 0
            out.append(line)
        else:
            run += 1
            if run <= max_blank:
                out.append("")
    return "\n".join(out)

