def run_length_decode(encoded: str) -> str:
    out: list[str] = []
    count = ""
    for ch in encoded:
        if "0" <= ch <= "9":
            count += ch
        else:
            out.append(ch * (int(count) if count else 1))
            count = ""
    if count:
        raise ValueError("encoded string ends with a dangling count")
    return "".join(out)

def wrap_words_greedy(text: str, width: int) -> list[str]:
    lines: list[str] = []
    current = ""
    for word in text.split():
        if not current:
            current = word
        elif len(current) + 1 + len(word) <= width:
            current += " " + word
        else:
            lines.append(current)
            current = word
    if current:
        lines.append(current)
    return lines

