def strip_html_tags(markup: str) -> str:
    text = re.sub(r"<[^>]*>", "", markup)
    named = {"amp": "&", "lt": "<", "gt": ">", "quot": '"'}

    def decode(m: re.Match) -> str:
        name = m.group(1)
        if name in named:
            return named[name]
        if name.startswith("#"):
            code = int(name[1:])
            if code <= 0x10FFFF:
                return chr(code)
        return m.group(0)

    return re.sub(r"&(#[0-9]+|[A-Za-z]+);", decode, text)

