def expand_number_ranges(spec: str) -> list[int]:
    def to_int(s: str) -> int:
        s = s.strip()
        if not (s.isascii() and s.isdigit()):
            raise ValueError(f"invalid number: {s!r}")
        return int(s)

    values: set[int] = set()
    for item in spec.split(","):
        if not item.strip():
            continue
        if "-" in item:
            lo_text, _, hi_text = item.partition("-")
            lo, hi = to_int(lo_text), to_int(hi_text)
            if lo > hi:
                raise ValueError(f"descending range: {item.strip()!r}")
            values.update(range(lo, hi + 1))
        else:
            values.add(to_int(item))
    return sorted(values)

