import re


def render_brace_template(template: str, values: dict[str, str]) -> str:
    token = re.compile(r"\{\{|\}\}|\{([A-Za-z_][A-Za-z0-9_]*)\}|[{}]")

    def replace(m: re.Match) -> str:
        text = m.group(0)
        if text == "{{":
            return "{"
        if text == "}}":
            return "}"
        if m.group(1) is not None:
            return values[m.group(1)]
        raise ValueError(f"unmatched brace at position {m.start()}")

    return token.sub(replace, template)

