def parse_byte_size(size: str) -> int:
    m = re.fullmatch(r"\s*([0-9]+(?:\.[0-9]+)?)\s*([A-Za-z]*)\s*", size)
    if not m:
        raise ValueError(f"invalid size: {size!r}")
    number, unit = m.groups()
    powers = {
        "": 0, "b": 0,
        "k": 1, "kb": 1, "kib": 1,
        "m": 2, "mb": 2, "mib": 2,
        "g": 3, "gb": 3, "gib": 3,
        "t": 4, "tb": 4, "tib": 4,
    }
    key = unit.lower()
    if key not in powers:
        raise ValueError(f"unknown unit: {unit!r}")
    return round(Fraction(number) * 1024 ** powers[key])

import re


def parse_http_headers(raw: str) -> dict[str, str]:
    headers: dict[str, str] = {}
    last: str | None = None
    for line in re.split(r"\r?\n", raw):
        if not line.strip():
            continue
        if line[0] in " \t":
            if last is None:
                raise ValueError("continuation line without a preceding header")
            headers[last] = f"{headers[last]} {line.strip()}"
            continue
        name, sep, value = line.partition(":")
        if not sep:
            raise ValueError(f"malformed header line: {line!r}")
        name, value = name.strip().lower(), value.strip()
        headers[name] = f"{headers[name]}, {value}" if name in headers else value
        last = name
    return headers

