import re


def evaluate_arithmetic_expression(expression: str) -> float:
    tokens = re.findall(r"\s*([0-9]+(?:\.[0-9]+)?|[-+*/^()]|\S)", expression)
    pos = 0

    def peek() -> str | None:
        return tokens[pos] if pos < len(tokens) else None

    def take() -> str:
        nonlocal pos
        tok = peek()
        if tok is None:
            raise ValueError("unexpected end of expression")
        pos += 1
        return tok

    def parse_expr() -> float:
        value = parse_term()
        while peek() in ("+", "-"):
            op = take()
            rhs = parse_term()
            value = value + rhs if op == "+" else value - rhs
        return value

    def parse_term() -> float:
        value = parse_factor()
        while peek() in ("*", "/"):
            op = take()
            rhs = parse_factor()
            value = value * rhs if op == "*" else value / rhs
        return value

    def parse_factor() -> float:
        if peek() in ("+", "-"):
            op = take()
            operand = parse_factor()
            return operand if op == "+" else -operand
        return parse_power()

    def parse_power() -> float:
        base = parse_atom()
        if peek() == "^":
            take()
            result = base ** parse_factor()
            if isinstance(result, complex):
                raise ValueError("result is not a real number")
            return result
        return base

    def parse_atom() -> float:
        tok = take()
        if tok == "(":
            value = parse_expr()
            if take() != ")":
                raise ValueError("expected ')'")
            return value
        if tok[0] in "0123456789":
            return float(tok)
        raise ValueError(f"unexpected token {tok!r}")

    result = parse_expr()
    if pos != len(tokens):
        raise ValueError(f"unexpected token {tokens[pos]!r}")
    return float(result)

import re


def parse_mini_json(text: str) -> object:
    whitespace = " \t\n\r"
    escapes = {'"': '"', "\\": "\\", "/": "/", "n": "\n", "t": "\t", "r": "\r", "b": "\b", "f": "\f"}
    number_re = re.compile(r"-?(?:0|[1-9][0-9]*)(\.[0-9]+)?([eE][-+]?[0-9]+)?")
    n = len(text)
    i = 0

    def skip_ws() -> None:
        nonlocal i
        while i < n and text[i] in whitespace:
            i += 1

    def expect(ch: str) -> None:
        nonlocal i
        if i >= n or text[i] != ch:
            raise ValueError(f"expected {ch!r} at position {i}")
        i += 1

    def parse_value() -> object:
        nonlocal i
        skip_ws()
        if i >= n:
            raise ValueError("unexpected end of input")
        ch = text[i]
        if ch == "{":
            return parse_object()
        if ch == "[":
            return parse_array()
        if ch == '"':
            return parse_string()
        for word, value in (("true", True), ("false", False), ("null", None)):
            if text.startswith(word, i):
                i += len(word)
                return value
        m = number_re.match(text, i)
        if m:
            i = m.end()
            if m.group(1) or m.group(2):
                return float(m.group(0))
            return int(m.group(0))
        raise ValueError(f"unexpected character {ch!r} at position {i}")

    def parse_string() -> str:
        nonlocal i
        expect('"')
        out: list[str] = []
        while True:
            if i >= n:
                raise ValueError("unterminated string")
            ch = text[i]
            i += 1
            if ch == '"':
                return "".join(out)
            if ch == "\\":
                if i >= n:
                    raise ValueError("unterminated escape")
                esc = text[i]
                i += 1
                if esc in escapes:
                    out.append(escapes[esc])
                elif esc == "u":
                    digits = text[i:i + 4]
                    if len(digits) != 4 or any(c not in "0123456789abcdefABCDEF" for c in digits):
                        raise ValueError("invalid unicode escape")
                    out.append(chr(int(digits, 16)))
                    i += 4
                else:
                    raise ValueError(f"invalid escape {esc!r}")
            elif ch < " ":
                raise ValueError("control character in string")
            else:
                out.append(ch)

    def parse_array() -> list:
        nonlocal i
        expect("[")
        items: list = []
        skip_ws()
        if i < n and text[i] == "]":
            i += 1
            return items
        while True:
            items.append(parse_value())
            skip_ws()
            if i < n and text[i] == ",":
                i += 1
                continue
            expect("]")
            return items

    def parse_object() -> dict:
        nonlocal i
        expect("{")
        obj: dict = {}
        skip_ws()
        if i < n and text[i] == "}":
            i += 1
            return obj
        while True:
            skip_ws()
            if i >= n or text[i] != '"':
                raise ValueError(f"expected string key at position {i}")
            key = parse_string()
            skip_ws()
            expect(":")
            obj[key] = parse_value()
            skip_ws()
            if i < n and text[i] == ",":
                i += 1
                continue
            expect("}")
            return obj

    value = parse_value()
    skip_ws()
    if i != n:
        raise ValueError(f"trailing data at position {i}")
    return value

