def split_shell_words(command: str) -> list[str]:
    words: list[str] = []
    current: list[str] = []
    in_word = False
    i, n = 0, len(command)
    while i < n:
        ch = command[i]
        if ch.isspace():
            if in_word:
                words.append("".join(current))
                current, in_word = [], False
            i += 1
        elif ch == "'":
            end = command.find("'", i + 1)
            if end == -1:
                raise ValueError("unterminated single quote")
            current.append(command[i + 1:end])
            in_word = True
            i = end + 1
        elif ch == '"':
            i += 1
            while True:
                if i >= n:
                    raise ValueError("unterminated double quote")
                c = command[i]
                if c == '"':
                    i += 1
                    break
                if c == "\\" and i + 1 < n and command[i + 1] in '"\\':
                    current.append(command[i + 1])
                    i += 2
                else:
                    current.append(c)
                    i += 1
            in_word = True
        elif ch == "\\":
            if i + 1 >= n:
                raise ValueError("trailing backslash")
            current.append(command[i + 1])
            in_word = True
            i += 2
        else:
            current.append(ch)
            in_word = True
            i += 1
    if in_word:
        words.append("".join(current))
    return words

import re


def infix_to_postfix(expression: str) -> str:
    tokens = re.findall(r"[A-Za-z0-9]+|\S", expression)
    if not tokens:
        return ""
    prec = {"+": 1, "-": 1, "*": 2, "/": 2, "^": 3}
    output: list[str] = []
    stack: list[str] = []
    expect_operand = True
    for tok in tokens:
        if re.fullmatch(r"[A-Za-z0-9]+", tok):
            if not expect_operand:
                raise ValueError(f"unexpected operand {tok!r}")
            output.append(tok)
            expect_operand = False
        elif tok == "(":
            if not expect_operand:
                raise ValueError("unexpected '('")
            stack.append(tok)
        elif tok == ")":
            if expect_operand:
                raise ValueError("unexpected ')'")
            while stack and stack[-1] != "(":
                output.append(stack.pop())
            if not stack:
                raise ValueError("unbalanced ')'")
            stack.pop()
        elif tok in prec:
            if expect_operand:
                raise ValueError(f"unexpected operator {tok!r}")
            while stack and stack[-1] != "(" and (
                prec[stack[-1]] > prec[tok] or (prec[stack[-1]] == prec[tok] and tok != "^")
            ):
                output.append(stack.pop())
            stack.append(tok)
            expect_operand = True
        else:
            raise ValueError(f"unknown character {tok!r}")
    if expect_operand:
        raise ValueError("expression ends unexpectedly")
    while stack:
        op = stack.pop()
        if op == "(":
            raise ValueError("unbalanced '('")
        output.append(op)
    return " ".join(output)

import re


def parse_s_expression(text: str) -> object:
    tokens = re.findall(r"[()]|[^\s()]+", text)
    if not tokens:
        raise ValueError("empty input")

    def atom(tok: str) -> object:
        return int(tok) if re.fullmatch(r"[+-]?[0-9]+", tok) else tok

    stack: list[list] = []
    result: object = None
    done = False
    for tok in tokens:
        if done:
            raise ValueError(f"unexpected token after expression: {tok!r}")
        if tok == "(":
            stack.append([])
        elif tok == ")":
            if not stack:
                raise ValueError("unexpected ')'")
            finished = stack.pop()
            if stack:
                stack[-1].append(finished)
            else:
                result, done = finished, True
        elif stack:
            stack[-1].append(atom(tok))
        else:
            result, done = atom(tok), True
    if stack:
        raise ValueError("unbalanced '('")
    return result

import re


def decode_bencode(data: str) -> object:
    pos = 0

    def parse() -> object:
        nonlocal pos
        if pos >= len(data):
            raise ValueError("unexpected end of data")
        ch = data[pos]
        if ch == "i":
            end = data.find("e", pos)
            if end == -1:
                raise ValueError("unterminated integer")
            body = data[pos + 1:end]
            if not re.fullmatch(r"0|-?[1-9][0-9]*", body):
                raise ValueError(f"invalid integer {body!r}")
            pos = end + 1
            return int(body)
        if ch == "l":
            pos += 1
            items = []
            while pos < len(data) and data[pos] != "e":
                items.append(parse())
            if pos >= len(data):
                raise ValueError("unterminated list")
            pos += 1
            return items
        if ch == "d":
            pos += 1
            result = {}
            while pos < len(data) and data[pos] != "e":
                if not "0" <= data[pos] <= "9":
                    raise ValueError("dictionary key must be a string")
                key = parse()
                result[key] = parse()
            if pos >= len(data):
                raise ValueError("unterminated dictionary")
            pos += 1
            return result
        if "0" <= ch <= "9":
            colon = data.find(":", pos)
            if colon == -1:
                raise ValueError("missing ':' after string length")
            length_text = data[pos:colon]
            if not re.fullmatch(r"0|[1-9][0-9]*", length_text):
                raise ValueError(f"invalid string length {length_text!r}")
            start = colon + 1
            end = start + int(length_text)
            if end > len(data):
                raise ValueError("string runs past end of data")
            pos = end
            return data[start:end]
        raise ValueError(f"unexpected character {ch!r} at position {pos}")

    value = parse()
    if pos != len(data):
        raise ValueError("trailing data")
    return value

tests:
assert decode_bencode("le") == []
assert decode_bencode("de") == {}
assert decode_bencode("i0e") == 0
assert decode_bencode("5:a:b:e") == "a:b:e"
assert decode_bencode("ll1:xelee") == [["x"], []]
for bad in ["i03e", "i-0e", "ie", "4:spa", "i1ei2e", "di1e1:ae", "", "l1:a", "x", "02:ab"]:
    try:
        decode_bencode(bad)
        assert False, bad
    except ValueError:
        pass

