def glob_match(pattern: str, text: str) -> bool:
    # Compile the pattern into single-character elements and '*' markers.
    elements: list[tuple] = []
    i, n = 0, len(pattern)
    while i < n:
        ch = pattern[i]
        if ch == "*":
            if not elements or elements[-1] != ("*",):
                elements.append(("*",))
            i += 1
        elif ch == "?":
            elements.append(("?",))
            i += 1
        elif ch == "[":
            j = i + 1
            negate = j < n and pattern[j] == "!"
            if negate:
                j += 1
            start = j
            if j < n and pattern[j] == "]":
                j += 1
            while j < n and pattern[j] != "]":
                j += 1
            if j >= n:
                elements.append(("lit", "["))
                i += 1
                continue
            body = pattern[start:j]
            members = []
            k = 0
            while k < len(body):
                if k + 2 < len(body) and body[k + 1] == "-":
                    members.append((body[k], body[k + 2]))
                    k += 3
                else:
                    members.append((body[k], body[k]))
                    k += 1
            elements.append(("set", negate, members))
            i = j + 1
        else:
            elements.append(("lit", ch))
            i += 1

    def matches_one(element: tuple, c: str) -> bool:
        kind = element[0]
        if kind == "?":
            return True
        if kind == "lit":
            return element[1] == c
        _, negate, members = element
        return any(lo <= c <= hi for lo, hi in members) != negate

    # Greedy match with backtracking to the most recent star: O(len(p) * len(t)).
    p = t = 0
    star_p, star_t = -1, 0
    while t < len(text):
        if p < len(elements) and elements[p][0] == "*":
            star_p, star_t = p, t
            p += 1
        elif p < len(elements) and matches_one(elements[p], text[t]):
            p += 1
            t += 1
        elif star_p != -1:
            star_t += 1
            t = star_t
            p = star_p + 1
        else:
            return False
    while p < len(elements) and elements[p][0] == "*":
        p += 1
    return p == len(elements)

def expand_cron_field(field: str, low: int, high: int) -> list[int]:
    def number(text: str) -> int:
        if not (text.isascii() and text.isdigit()):
            raise ValueError(f"invalid number {text!r}")
        value = int(text)
        if not low <= value <= high:
            raise ValueError(f"value {value} out of range {low}-{high}")
        return value

    selected: set[int] = set()
    for item in field.split(","):
        base, slash, step_text = item.partition("/")
        if slash:
            if not (step_text.isascii() and step_text.isdigit()) or int(step_text) == 0:
                raise ValueError(f"invalid step {step_text!r}")
            step = int(step_text)
        else:
            step = 1
        if base == "*":
            start, end = low, high
        elif "-" in base:
            a, _, b = base.partition("-")
            start, end = number(a), number(b)
            if start > end:
                raise ValueError(f"descending range {base!r}")
        else:
            start = number(base)
            end = high if slash else start
        selected.update(range(start, end + 1, step))
    return sorted(selected)

tests:
assert expand_cron_field("*", 1, 3) == [1, 2, 3]
assert expand_cron_field("0", 0, 0) == [0]
assert expand_cron_field("1,1,1", 0, 5) == [1]
assert expand_cron_field("*/2", 1, 7) == [1, 3, 5, 7]
for bad, lo, hi in [("7", 0, 6), ("5-1", 0, 9), ("*/0", 0, 5), ("", 0, 5), ("a", 0, 5), ("1,,2", 0, 5), ("1-", 0, 5)]:
    try:
        expand_cron_field(bad, lo, hi)
        assert False, bad
    except ValueError:
        pass
